"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["33088"],{40622(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.agregado_sobre_dominio_que_nao_agrega","status":422,"titulo":"O agregado resume fato de membro booleano ou categ\xf3rico"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.agregado_sobre_dominio_que_nao_agrega","requisitos":["UNI-REQ-0143","UNI-REQ-0146"],"oQueAconteceu":["O administrador cadastrou um fato que resume respostas de grupo (`POST /api/configuracao/admin/fatos-candidato/agregados`) sobre um fato de membro cujo tipo de dado \xe9 n\xfamero, texto, data ou endere\xe7o. H\xe1 dois tipos de resumo do grupo repet\xedvel (UNI-REQ-0146): \\"existe membro que\u2026\\", sobre um fato booleano, e \\"valores presentes\\", sobre um fato categ\xf3rico. Os outros tipos de dado n\xe3o t\xeam resumo.","A recusa vem na lista `errors` da resposta, com `field` igual a `fatoDeMembro`. Ela s\xf3 \xe9 dada quando o fato de membro existe e \xe9 declarado de membro de grupo: com um c\xf3digo que n\xe3o existe a recusa \xe9 [a do fato de membro fora do cat\xe1logo](/erros/uniplus.configuracao.fato_candidato.agregado_sem_fato_de_membro), e com um fato que n\xe3o \xe9 de membro de grupo, [a do fato que n\xe3o \xe9 de membro de grupo](/erros/uniplus.configuracao.fato_candidato.agregado_sobre_fato_que_nao_eh_campo_de_grupo). Se o fato de membro tamb\xe9m estiver desativado, a lista traz ainda a recusa de dado do candidato desativado (`uniplus.vinculo_catalogo.fato_desativado`), com a mensagem que nomeia o dado de membro. Nada \xe9 gravado."],"comoResolver":["Escolha como fato de membro um fato booleano ou categ\xf3rico do grupo. Se o dado que se quer resumir \xe9 de outro tipo, cadastre um fato de membro booleano ou categ\xf3rico que o represente, e use esse fato no resumo de grupo."],"ondeAparece":["Cadastro de um fato do cat\xe1logo que resume respostas de grupo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);